<?php
namespace App\Modules\Accompagnement\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Accompagnement\Services\MissionAccess as Access;
use App\Modules\Tenancy\Services\OfficineAccess as Office;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class MissionDiagnosticController extends Controller {
 private const ANSWERS=['conform','gap','not_applicable','not_evaluated'];
 private function mission(Request $r,string $id,bool $write=false):array{
  $office=(int)app('tenant.officine_id');Access::lockOffice($r,$office);$m=DB::table('support_missions as m')->join('support_requests as q','q.id','=','m.support_request_id')->where('q.officine_id',$office)->where('m.id',$id)->select('m.*')->first();abort_unless($m&&Access::allowed($r,$office,$m->id,$write,$write),404);if($write)abort_unless($m->status==='active',409,'Mission non active.');return [$office,$m];
 }
 private function keyRules():array{return ['request_key'=>['required','string','min:16','max:80','regex:/^[A-Za-z0-9-]+$/'],'confirmed'=>['required','accepted']];}
 private function questionRules():array{return ['title'=>['required','string','max:180','regex:/\S/u'],'questions'=>['present','array','max:60'],'questions.*.key'=>['required','string','max:80','regex:/^[A-Za-z0-9-]+$/','distinct'],'questions.*.label'=>['required','string','max:1000','regex:/\S/u'],'questions.*.required'=>['required','boolean'],'questions.*.source'=>['nullable','string','max:1500'],'questions.*.choices'=>['required','array','min:1','max:4'],'questions.*.choices.*'=>['required','in:conform,gap,not_applicable,not_evaluated']];}
 private function questions(array $d):array{return array_map(function($q){return ['key'=>$q['key'],'label'=>trim($q['label']),'required'=>(bool)$q['required'],'source'=>trim($q['source']??''),'choices'=>array_values(array_unique($q['choices']))];},$d['questions']);}
 private function fail(string $message):never{throw ValidationException::withMessages(['diagnostic'=>$message]);}
 private function audit(Request $r,int $office,object $m,string $action):void{Office::audit($r,$office,'support.diagnostic.'.$action,['request_id'=>$m->support_request_id]);}
 private function record(string $table,object $m,string|int $id):object{$row=DB::table($table)->where('mission_id',$m->id)->where('id',$id)->lockForUpdate()->first();abort_unless($row,404);return $row;}
 public function index(Request $r,string $id){return DB::transaction(function()use($r,$id){[$office,$m]=$this->mission($r,$id);$lead=Access::allowed($r,$office,$m->id,true,true);$templates=DB::table('support_diagnostic_templates')->where('mission_id',$m->id);$diagnostics=DB::table('support_diagnostics')->where('mission_id',$m->id);if(!$lead){$templates->where('status','published');$diagnostics->where('status','shared');}
  $models=$templates->orderByDesc('id')->get(['id','parent_id','family_key','revision','version','title','questions','status','published_at'])->map(function($t){$t->questions=json_decode($t->questions,true);return $t;});$rows=$diagnostics->orderByDesc('id')->get(['id','template_id','previous_id','revision','version','type','assessed_on','template_snapshot','answers','status','created_by','submitted_at','shared_at'])->map(function($d){$d->template_snapshot=json_decode($d->template_snapshot,true);$d->answers=json_decode($d->answers,true);return $d;});return response()->json(['templates'=>$models,'diagnostics'=>$rows,'can_lead'=>$lead])->header('Cache-Control','no-store');});}
 public function createTemplate(Request $r,string $id){$d=$r->validate($this->questionRules()+$this->keyRules()+['parent_id'=>['nullable','integer','min:1']]);$questions=$this->questions($d);$fingerprint=hash('sha256',json_encode([$r->user()->id,$d['title'],$questions,$d['parent_id']??null]));return DB::transaction(function()use($r,$id,$d,$questions,$fingerprint){[$office,$m]=$this->mission($r,$id,true);$existing=DB::table('support_diagnostic_templates')->where('mission_id',$m->id)->where('request_key',$d['request_key'])->first();if($existing){abort_unless(hash_equals($existing->fingerprint,$fingerprint),409);return response()->json(['id'=>$existing->id]);}
  $family=(string)Str::uuid();$revision=1;if(!empty($d['parent_id'])){$parent=$this->record('support_diagnostic_templates',$m,$d['parent_id']);abort_unless($parent->status==='published',409,'Le modèle parent doit être publié.');$family=$parent->family_key;abort_if(DB::table('support_diagnostic_templates')->where('mission_id',$m->id)->where('family_key',$family)->where('status','draft')->exists(),409,'Une révision est déjà en préparation.');$revision=(int)DB::table('support_diagnostic_templates')->where('mission_id',$m->id)->where('family_key',$family)->max('revision')+1;}
  $model=DB::table('support_diagnostic_templates')->insertGetId(['mission_id'=>$m->id,'parent_id'=>$d['parent_id']??null,'family_key'=>$family,'revision'=>$revision,'request_key'=>$d['request_key'],'fingerprint'=>$fingerprint,'title'=>trim($d['title']),'questions'=>json_encode($questions),'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,$office,$m,'template_draft_created');return response()->json(['id'=>$model],201);});}
 public function saveTemplate(Request $r,string $id,string $templateId){$d=$r->validate($this->questionRules()+['version'=>['required','integer','min:1']]);return DB::transaction(function()use($r,$id,$templateId,$d){[$office,$m]=$this->mission($r,$id,true);$t=$this->record('support_diagnostic_templates',$m,$templateId);abort_unless($t->status==='draft'&&$t->version===(int)$d['version'],409,'Modèle figé ou périmé.');DB::table('support_diagnostic_templates')->where('id',$t->id)->update(['title'=>trim($d['title']),'questions'=>json_encode($this->questions($d)),'version'=>$t->version+1,'updated_at'=>now()]);$this->audit($r,$office,$m,'template_draft_saved');return response()->json(['message'=>'Brouillon enregistré.']);});}
 public function publishTemplate(Request $r,string $id,string $templateId){$d=$r->validate(['version'=>['required','integer','min:1'],'confirmed'=>['required','accepted']]);return DB::transaction(function()use($r,$id,$templateId,$d){[$office,$m]=$this->mission($r,$id,true);$t=$this->record('support_diagnostic_templates',$m,$templateId);abort_unless($t->status==='draft'&&$t->version===(int)$d['version'],409);if(!count(json_decode($t->questions,true)))$this->fail('Ajoutez au moins une question avant publication.');DB::table('support_diagnostic_templates')->where('id',$t->id)->update(['status'=>'published','version'=>$t->version+1,'published_at'=>now(),'updated_at'=>now()]);Access::event($r,$m,$office,'diagnostic_template_published','Un modèle de diagnostic a été publié, sans score réglementaire.');return response()->json(['message'=>'Version publiée et figée.']);});}
 public function create(Request $r,string $id){$d=$r->validate($this->keyRules()+['template_id'=>['required','integer','min:1'],'type'=>['required','in:initial,followup'],'assessed_on'=>['required','date_format:Y-m-d','before_or_equal:'.now('Africa/Porto-Novo')->toDateString()],'previous_id'=>['nullable','integer','min:1']]);$fingerprint=hash('sha256',json_encode([$r->user()->id,(int)$d['template_id'],$d['type'],$d['assessed_on'],$d['previous_id']??null]));return DB::transaction(function()use($r,$id,$d,$fingerprint){[$office,$m]=$this->mission($r,$id,true);$existing=DB::table('support_diagnostics')->where('mission_id',$m->id)->where('request_key',$d['request_key'])->first();if($existing){abort_unless(hash_equals($existing->fingerprint,$fingerprint),409);return response()->json(['id'=>$existing->id]);}$t=$this->record('support_diagnostic_templates',$m,$d['template_id']);abort_unless($t->status==='published',409,'Modèle publié requis.');$revision=1;$answers=[];if(!empty($d['previous_id'])){$previous=$this->record('support_diagnostics',$m,$d['previous_id']);abort_unless($previous->status==='shared'&&$previous->template_id===(int)$d['template_id']&&$previous->type===$d['type'],409,'Révision : même modèle figé et diagnostic partagé requis.');abort_if(DB::table('support_diagnostics')->where('previous_id',$previous->id)->exists(),409,'Une révision existe déjà.');$revision=$previous->revision+1;$answers=json_decode($previous->answers,true);}
  $diagnostic=DB::table('support_diagnostics')->insertGetId(['mission_id'=>$m->id,'template_id'=>$t->id,'previous_id'=>$d['previous_id']??null,'revision'=>$revision,'request_key'=>$d['request_key'],'fingerprint'=>$fingerprint,'type'=>$d['type'],'assessed_on'=>$d['assessed_on'],'template_snapshot'=>json_encode(['id'=>$t->id,'title'=>$t->title,'family_key'=>$t->family_key,'revision'=>$t->revision,'questions'=>json_decode($t->questions,true)]),'answers'=>json_encode($answers),'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,$office,$m,'draft_created');return response()->json(['id'=>$diagnostic],201);});}
 private function answers(object $diagnostic,array $answers,bool $complete):array{
  $questions=collect(json_decode($diagnostic->template_snapshot,true)['questions'])->keyBy('key');$clean=[];$seen=[];
  foreach($answers as $answer){$key=$answer['key'];if(isset($seen[$key]))$this->fail('Question répétée.');$seen[$key]=true;$q=$questions->get($key);if(!$q)$this->fail('Question étrangère au modèle figé.');if(!in_array($answer['answer'],$q['choices'],true))$this->fail('Réponse non autorisée par ce modèle.');$note=trim($answer['note']??'');if($answer['answer']==='not_applicable'&&$note==='')$this->fail('Justification obligatoire pour une réponse non applicable.');$clean[]=['key'=>$key,'answer'=>$answer['answer'],'note'=>$note];}
  if($complete)foreach($questions as $q)if($q['required']&&!isset($seen[$q['key']]))$this->fail('Toutes les questions obligatoires doivent être renseignées.');return $clean;
 }
 public function save(Request $r,string $id,string $diagnosticId){$d=$r->validate(['version'=>['required','integer','min:1'],'answers'=>['present','array','max:60'],'answers.*.key'=>['required','string','max:80'],'answers.*.answer'=>['required','in:'.implode(',',self::ANSWERS)],'answers.*.note'=>['nullable','string','max:3000']]);return DB::transaction(function()use($r,$id,$diagnosticId,$d){[$office,$m]=$this->mission($r,$id,true);$row=$this->record('support_diagnostics',$m,$diagnosticId);abort_unless($row->status==='draft'&&$row->version===(int)$d['version'],409,'Diagnostic figé ou périmé.');$answers=$this->answers($row,$d['answers'],false);DB::table('support_diagnostics')->where('id',$row->id)->update(['answers'=>json_encode($answers),'version'=>$row->version+1,'updated_at'=>now()]);$this->audit($r,$office,$m,'draft_saved');return response()->json(['message'=>'Brouillon enregistré, non partagé.']);});}
 public function decision(Request $r,string $id,string $diagnosticId){$d=$r->validate(['version'=>['required','integer','min:1'],'action'=>['required','in:submit,share'],'confirmed'=>['required','accepted']]);return DB::transaction(function()use($r,$id,$diagnosticId,$d){[$office,$m]=$this->mission($r,$id,true);$row=$this->record('support_diagnostics',$m,$diagnosticId);$shared=$d['action']==='share';abort_unless($row->version===(int)$d['version']&&$row->status===($shared?'submitted':'draft'),409,'Version périmée ou transition incompatible. Actualisez le diagnostic.');$this->answers($row,json_decode($row->answers,true),true);DB::table('support_diagnostics')->where('id',$row->id)->update(['status'=>$shared?'shared':'submitted','version'=>$row->version+1,$shared?'shared_at':'submitted_at'=>now(),'updated_at'=>now()]);if($shared){Access::event($r,$m,$office,'diagnostic_shared','Un diagnostic versionné a été partagé. Aucun score réglementaire.');Outbox::office($office,'mission-diagnostic:'.$row->id.':shared','Diagnostic partagé','Un diagnostic de votre mission est disponible dans votre espace autorisé.');}else $this->audit($r,$office,$m,'submitted');return response()->json(['message'=>$shared?'Diagnostic partagé.':'Version soumise et figée, non partagée.']);});}
}
